                          double *workd, double *workl);

static void csr_matvec(int32_t n, const int32_t *indptr, const int32_t *indices,
                       const double *data, const double *x, double *y) {
    for (int32_t i = 0; i < n; i++) {
        double s = 0.0;
        int32_t a = indptr[i];
        int32_t b = indptr[i + 1];
        for (int32_t j = a; j < b; j++) {
            s += data[j] * x[indices[j]];
        }
        y[i] = s;
    }
}

/* solve(indptr, indices, data, n, k, ncv, maxiter, tol, v0) -> (dr, di, z)
   z is Fortran-ordered (n, k+1) float64 raw Ritz vectors as ARPACK returns them.
   We return the raw dr, di, zr so Python can do the conjugate-pair assembly,
   OR we assemble here. Assemble here to match scipy.
*/
static PyObject *ceigs_solve(PyObject *self, PyObject *args) {
    Py_buffer indptr_b, indices_b, data_b, v0_b;
    int n, k, ncv, maxiter;
    double tol;
    if (!PyArg_ParseTuple(args, "y*y*y*iiiid y*",
                          &indptr_b, &indices_b, &data_b,
                          &n, &k, &ncv, &maxiter, &tol, &v0_b)) {
        return NULL;
    }
    const int32_t *indptr = (const int32_t *)indptr_b.buf;
    const int32_t *indices = (const int32_t *)indices_b.buf;
    const double *data = (const double *)data_b.buf;
    const double *v0 = (const double *)v0_b.buf;

    state_d st;
    memset(&st, 0, sizeof(st));
    st.tol = tol;
    st.which = 0; /* LM? need to confirm encoding. We'll probe. */
    st.ido = 0;
    st.info = 1; /* start from resid = v0 */
    st.bmat = 0;
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.maxiter = maxiter;
    st.shift = 1;

    double *resid = (double *)malloc(sizeof(double) * n);
    double *v = (double *)calloc((size_t)n * ncv, sizeof(double));
    double *workd = (double *)calloc(3 * (size_t)n, sizeof(double));
    int lworkl = 3 * ncv * (ncv + 2);
    double *workl = (double *)calloc(lworkl, sizeof(double));
    int32_t *ipntr = (int32_t *)calloc(14, sizeof(int32_t));
    memcpy(resid, v0, sizeof(double) * n);

    int guard = maxiter * (ncv + 10) + 1000;
    int steps = 0;
    while (steps < guard) {
        ARNAUD_dnaupd(&st, resid, v, ipntr, workd, workl);
        steps++;
        int ido = st.ido;
        if (ido == 1 || ido == 5 || ido == -1) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            csr_matvec(n, indptr, indices, data, workd + x0, workd + y0);
        } else if (ido == 2) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            memcpy(workd + y0, workd + x0, sizeof(double) * n);
        } else if (ido == 4) {
            for (int i = 0; i < n; i++) resid[i] = 1.0;
        } else {
            break;
        }
    }

    PyObject *res = Py_BuildValue("ii", st.ido, st.info);
    free(resid); free(v); free(workd); free(workl); free(ipntr);
    PyBuffer_Release(&indptr_b);
    PyBuffer_Release(&indices_b);
    PyBuffer_Release(&data_b);
    PyBuffer_Release(&v0_b);
    return res;
}

static PyMethodDef methods[] = {
    {"solve", ceigs_solve, METH_VARARGS, "probe"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "ceigs", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_ceigs(void) { return PyModule_Create(&moduledef); }
