                   const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        int32_t a = ip[i], b = ip[i+1];
        for (int32_t j = a; j < b; j++) s += data[j] * x[idx[j]];
        y[i] = s;
